import{_ as e,o as a,c as s,a2 as n}from"./chunks/framework.BEmfQga0.js";const g=JSON.parse('{"title":"Host Adapters","description":"","frontmatter":{},"headers":[],"relativePath":"platform-concepts/host-adapters.md","filePath":"platform-concepts/host-adapters.md","lastUpdated":1788258471000}'),o={name:"platform-concepts/host-adapters.md"};function p(i,t,l,r,d,c){return a(),s("div",null,[...t[0]||(t[0]=[n(`<h1 id="host-adapters" tabindex="-1">Host Adapters <a class="header-anchor" href="#host-adapters" aria-label="Permalink to &quot;Host Adapters&quot;">​</a></h1><p>A host adapter is the <strong>integration layer</strong> between an agent host and the LightRSI core runtime. It translates host-specific events, APIs, and configuration into the standardized format that plugins expect. OpenClaw, Codex, and Claude Code provide the full TokenPilot surfaces; DeepSeek Harness currently provides a narrower compatibility adapter.</p><h2 id="why-adapters-exist" tabindex="-1">Why Adapters Exist <a class="header-anchor" href="#why-adapters-exist" aria-label="Permalink to &quot;Why Adapters Exist&quot;">​</a></h2><p>Agent hosts differ in:</p><ul><li><strong>Event models</strong>: how they signal session start, message received, tool called, session end</li><li><strong>Configuration</strong>: where and how settings are stored (JSON, TOML, env vars)</li><li><strong>Context APIs</strong>: how the prompt/context is assembled and sent to the model</li><li><strong>Hook systems</strong>: how external code can intercept or modify behavior</li></ul><p>The adapter abstracts these differences so plugins only deal with one consistent interface.</p><h2 id="adapter-responsibilities" tabindex="-1">Adapter Responsibilities <a class="header-anchor" href="#adapter-responsibilities" aria-label="Permalink to &quot;Adapter Responsibilities&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                Host Adapter                 │</span></span>
<span class="line"><span>├────────────────────────────────────────────┤</span></span>
<span class="line"><span>│  1. Event translation                      │</span></span>
<span class="line"><span>│     Host-specific events → standard events  │</span></span>
<span class="line"><span>├────────────────────────────────────────────┤</span></span>
<span class="line"><span>│  2. Configuration integration              │</span></span>
<span class="line"><span>│     Reads host config, merges with plugin   │</span></span>
<span class="line"><span>│     config, writes back when needed         │</span></span>
<span class="line"><span>├────────────────────────────────────────────┤</span></span>
<span class="line"><span>│  3. Context interception                    │</span></span>
<span class="line"><span>│     Hooks into the host&#39;s context pipeline  │</span></span>
<span class="line"><span>│     so plugins can read/modify context      │</span></span>
<span class="line"><span>├────────────────────────────────────────────┤</span></span>
<span class="line"><span>│  4. Proxy / Gateway                         │</span></span>
<span class="line"><span>│     When the host doesn&#39;t support native    │</span></span>
<span class="line"><span>│     hooks, the adapter runs a local proxy   │</span></span>
<span class="line"><span>├────────────────────────────────────────────┤</span></span>
<span class="line"><span>│  5. CLI surface                             │</span></span>
<span class="line"><span>│     Exposes host-specific commands through  │</span></span>
<span class="line"><span>│     the shared lightrsi CLI                │</span></span>
<span class="line"><span>└────────────────────────────────────────────┘</span></span></code></pre></div><h2 id="current-adapters" tabindex="-1">Current Adapters <a class="header-anchor" href="#current-adapters" aria-label="Permalink to &quot;Current Adapters&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Host</th><th style="text-align:left;">Adapter Location</th><th style="text-align:left;">Integration Style</th></tr></thead><tbody><tr><td style="text-align:left;">OpenClaw</td><td style="text-align:left;"><code>components/adapters/openclaw/</code></td><td style="text-align:left;">Native plugin slot + restart</td></tr><tr><td style="text-align:left;">Codex</td><td style="text-align:left;"><code>components/adapters/codex/</code></td><td style="text-align:left;">Local proxy + hooks</td></tr><tr><td style="text-align:left;">Claude Code</td><td style="text-align:left;"><code>components/adapters/claude-code/</code></td><td style="text-align:left;">Local gateway + MCP</td></tr><tr><td style="text-align:left;">DeepSeek Harness</td><td style="text-align:left;"><code>components/adapters/deepseek-harness/</code></td><td style="text-align:left;">Cordis plugin + durable projection</td></tr></tbody></table><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/LightRSI/hosts/compatibility">Host Compatibility</a> — which features work on which host</li><li><a href="/LightRSI/host-adapter-development/adding-new-host">Adding a New Host</a> — build your own adapter</li><li><a href="/LightRSI/host-adapter-development/adapter-architecture">Adapter Architecture</a> — deep dive</li></ul>`,12)])])}const f=e(o,[["render",p]]);export{g as __pageData,f as default};
